/** Make Foundry's update and configuration messages container-specific. */

import { readFileSync, writeFileSync } from "node:fs";

export const CONFIGURATION_WARNING =
    "This instance of Foundry Virtual Tabletop is running in a Docker container.  " +
    "Its configuration is generated by the container at startup.  Changes made here will not persist between restarts.  " +
    'To change this behavior, set the CONTAINER_PRESERVE_CONFIG environment variable to "true".';

export const UPDATE_HINT =
    "This instance of Foundry Virtual Tabletop is running in a " +
    "Docker container.  To update, please pull a new Docker image and restart the container.";

export function patchLanguage(
    languageFile: string,
    preserveConfig: boolean,
): void {
    const data = JSON.parse(readFileSync(languageFile, "utf8")) as Record<
        string,
        unknown
    >;
    if (!preserveConfig) {
        data["SETUP.ConfigurationWarning"] = CONFIGURATION_WARNING;
    }
    data["SETUP.UpdateHint"] = data["SETUP.UpdateNoUpdateMode"] = UPDATE_HINT;
    writeFileSync(languageFile, JSON.stringify(data, null, "  "));
}
